from pathlib import Path
import sys,json,html,hashlib,collections
ROOT=Path(__file__).resolve().parents[3];sys.path.insert(0,str(ROOT))
from icon_set.model.icons.registry import create
from icon_set.renderers.svg import build_paths
SOURCE_ICON_ID=None
SOURCE_PATH='icon_set/work/solo-remaining-repair/review-decisions.json'
AUTHOR='gpt-6'
W=Path(__file__).parent;D=ROOT/'icon_set/dist';rows=json.loads((W/'review-decisions.json').read_text());cards=[];verified=[];esc=html.escape

def center(icon,q=None):
 paths=''.join('<path d="'+esc(p['d'],quote=True)+'"/>' for p in build_paths(icon.draw()))
 markers=''
 if q:
  ns=q['negative_space']
  for finding in [h for h in ns.get('holes',[]) if h['status']=='fail']+ns.get('pinches',[]):
   x,y,width,height=finding['bbox_viewbox'];markers+=f'<rect x="{x}" y="{y}" width="{max(width,.5)}" height="{max(height,.5)}" fill="none" stroke="#d93025" stroke-width=".65"/>'
 return '<svg class="center" viewBox="0 0 48 48" aria-label="Centerline"><g fill="none" stroke="currentColor" stroke-width="4" stroke-linecap="round" stroke-linejoin="round" opacity=".18">'+paths+'</g><g fill="none" stroke="#387cdd" stroke-width=".45">'+paths+'</g>'+markers+'</svg>'
for row in rows:
 ident=row['selected'];q=json.loads((D/'qa/solo'/ident/'metrics.json').read_text());blocked=row['decision']=='blocked';assert q['status']==('fail' if blocked else 'pass'),(ident,q['status'])
 folder='failed/solo48' if blocked else 'solo48';file=D/folder/(ident+'.svg');assert file.exists(),file
 assert hashlib.sha256(file.read_bytes()).hexdigest()==q['svg_sha256'],ident
 if not blocked:
  assert not q['errors'] and q['negative_space']['status']=='pass',ident
  assert q['svg_sha256']==row['svg_sha256'],ident
 verified.append(dict(number=row['number'],icon_id=ident,status=q['status'],holes=q['negative_space'].get('failed_hole_count'),pinches=q['negative_space'].get('pinch_count'),svg_sha256=q['svg_sha256']))
 icon=create(ident);label={'blocked':'Needs redesign','reconstructed':'Reconstructed','reviewed':'Preserved after review'}[row['decision']];before=''
 if ident!=row['icon_id']:
  before='<details><summary>Previous drawing</summary>'+center(create(row['icon_id']))+'</details>'
 extra='<ul>'+''.join('<li>'+esc(x)+'</li>' for x in q['errors'])+'</ul>' if blocked else '<p>Holes and pinches: clear.</p>'
 cards.append(f'<article data-batch="{(row["number"]-1)//100+1}" data-kind="{row["decision"]}"><h2>{row["number"]}. {esc(row["icon_id"])}</h2><span class="badge {row["decision"]}">{label}</span><div class="previews">{center(icon,q)}<div class="light"><img width="48" height="48" loading="lazy" src="../{folder}/{ident}.svg" alt="Light preview"></div><div class="dark"><img width="48" height="48" loading="lazy" src="../{folder}/{ident}.svg" alt="Dark preview"></div></div><p>{esc(row["reason"])}</p>{before}<details><summary>Check details</summary>{extra}<p>{icon.keyshape.name} · <a href="../{folder}/{ident}.svg">SVG</a> · <a href="../qa/solo/{ident}/metrics.json">Measurements</a></p></details></article>')
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Remaining solo icons — review</title><style>*{box-sizing:border-box}body{margin:0;padding:32px;background:#f5f4f0;color:#202936;font:15px/1.5 system-ui}header{max-width:1050px;margin-bottom:28px}h1{font-size:32px;line-height:1.15;margin:0 0 14px}.summary{font-size:19px}nav,.controls{display:flex;flex-wrap:wrap;gap:12px;align-items:center;margin:16px 0}main{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:16px}article{background:white;border:1px solid #deded9;border-radius:12px;padding:18px}h2{font-size:15px;overflow-wrap:anywhere;margin:0 0 9px}.badge{font-size:12px;border-radius:12px;background:#e2eee5;padding:4px 9px;color:#285439}.blocked{background:#fff0d1;color:#754512}.previews{display:flex;align-items:center;gap:12px;margin:16px 0}.center{width:96px;height:96px;flex-shrink:0}.light,.dark{padding:6px;border-radius:5px}.dark{background:#17191d}.dark img{filter:invert(1)}img{display:block}details{font-size:13px;margin-top:12px}summary{cursor:pointer}select,input,button{font:inherit;padding:9px 12px;border:1px solid #b8c0c8;background:white;border-radius:6px}button,a{color:#245eac}button{cursor:pointer}[hidden]{display:none!important}#count{color:#59636e}a{white-space:normal}li{overflow-wrap:anywhere}</style><header><h1>Remaining 500 solo icons reviewed</h1><p class="summary"><strong>492 build successfully</strong> · 8 need redesign</p><p>42 reconstructed versions and 450 preserved drawings. Blue lines show the centerlines; the small previews show the icons at their native 48px size in both themes.</p><p>Every cleared icon passes the hole and pinch checks. Preserved spacing advisories have a recorded visual decision tied to the exact drawing. Original versions remain available. The Failed build tab can still show preserved parent versions; this review counts the latest chosen version of each icon.</p><nav><a href="solo-review-batch-100.html">Earlier 100-icon review</a><a href="hole-review-batch-100.html">Firewall and mouse follow-up</a><button id="blocked">Show 8 unresolved icons</button></nav><div class="controls"><label>Batch <select id="batch"><option value="1">1 · icons 1–100</option><option value="2">2 · icons 101–200</option><option value="3">3 · icons 201–300</option><option value="4">4 · icons 301–400</option><option value="5">5 · icons 401–500</option><option value="">All five batches</option></select></label><label>Show <select id="kind"><option value="">All results</option><option value="reconstructed">Reconstructed</option><option value="reviewed">Preserved</option><option value="blocked">Needs redesign</option></select></label><input id="search" type="search" placeholder="Find an icon…" aria-label="Find an icon"></div><p id="count"></p></header><main>'''+''.join(cards)+'''</main><script>const b=document.querySelector('#batch'),k=document.querySelector('#kind'),s=document.querySelector('#search');function filter(){let count=0;document.querySelectorAll('article').forEach(c=>{c.hidden=!!((b.value&&c.dataset.batch!==b.value)||(k.value&&c.dataset.kind!==k.value)||(s.value&&!c.textContent.toLowerCase().includes(s.value.toLowerCase())));if(!c.hidden)count++});document.querySelector('#count').textContent=count+' icons shown'}[b,k,s].forEach(el=>el.addEventListener('input',filter));document.querySelector('#blocked').onclick=()=>{b.value='';k.value='blocked';s.value='';filter()};filter();</script></html>'''
(D/'gallery/solo-remaining-review.html').write_text(page);(W/'verified.json').write_text(json.dumps(verified,indent=2)+'\n')
md=['# Remaining 500 solo icons','','492 selected outputs built successfully:42 reconstructed variants and450 retained drawings.8 brand marks remain blocked. Original modules are preserved.','','## Review and references','','Reviewed all25 centerline sheets, each with20 icons and native light/dark previews. Revised geometry was separately inspected in3 comparison sheets. Local Lucide git-fork, sailboat, sword and camera originals and atomic-debug drawings informed shared nodes, coherent curves and sparse construction. Human changes use human_ref/full_body_ref.png and the previously reviewed user.svg. Keyshapes and rule thresholds were not weakened. The tall three-heart plant uses SQUARE to make room for wider leaf spacing.','','## Validation','','All500 final SVG hashes match their emitted QA records. All492 released choices have no model errors, no undersized holes and no pinches. Remaining sampled advisories retain their exact measured gaps and exact-pair review records.','','## Unresolved marks','']
for r in rows:
 if r['decision']=='blocked':md.append(f"- **{r['icon_id']}**: {r['reason']}")
md+=['','## Focused tests\n\n12 focused tests passed: exact-drawing review expiry and scope, continued certified-failure blocking, authored-stroke pinch checks, circle exceptions and raster connectivity. The broader existing suite was not rerun for these model-only edits.\n\n## Individual decisions','']
for r in rows:md.append(f"{r['number']}. **{r['icon_id']}** — {r['decision']}. {r['reason']} Selected: `{r['selected']}`.")
(W/'REPORT.md').write_text('\n'.join(md)+'\n');print('Verified500 final artifacts;492 released,8 blocked. Report saved.')
